EXEC model.apply_capability_from_dsl @document = N'{"contractId":"capability-from-dsl-change.v1","source":"capability read-run-state\nintent: The state of a run in the run store: read-run-evidence for the run and its principal, sliced to the run member (state, exit code, timing, output availability and graphs).\noutcome: status, runId and the run state; a run the store does not hold answers the store NOT_FOUND\ninquiry: What state is this run in?\ninput contract read-run-state-request.v1 {\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"runId\"],\"properties\":{\"principalId\":{\"type\":\"string\"},\"runId\":{\"type\":\"string\"}}}\noutput contract read-run-state-result.v1 {\"type\":\"object\",\"additionalProperties\":true}\ncli display outcome as json\nscenario read-run-state root terminal\ngiven: a run id and the principal whose run it is\nwhen: the kernel reads the run evidence and selects its state\nthen: the outcome is the run state\noperation read-run-state.prepare kind invoke-port port read-run-state-prepare\noperation read-run-state.read kind invoke-port port read-run-state-read\noperation read-run-state.select kind invoke-port port read-run-state-select\nplatform bind read-run-state-prepare\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"read-run-state-prepare\"}\nplatform bind read-run-state-read\nplatform: generic-capability-invocation.v1\nconfig: {\"providerId\":\"generic-capability-invocation\",\"authoritySource\":\"DATABASE\",\"capabilityIdPath\":\"executionTarget\",\"namespacePath\":\"executionNamespace\",\"scenarioPath\":\"executionScenario\",\"requestPath\":\"dispatchRequest\",\"resultPath\":\"result\",\"lineageMode\":\"retain-nested-execution\"}\nplatform bind read-run-state-select\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"read-run-state-select\"}","isMcpTooling":false}';
EXEC model.apply_capability_from_dsl @document = N'{"contractId":"capability-from-dsl-change.v1","source":"capability read-run-output\nintent: The output of a run in the run store: read-run-evidence for the run and its principal, sliced to the output member.\noutcome: status, runId and the run output; a run the store does not hold answers the store NOT_FOUND\ninquiry: What did this run return?\ninput contract read-run-output-request.v1 {\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"runId\"],\"properties\":{\"principalId\":{\"type\":\"string\"},\"runId\":{\"type\":\"string\"}}}\noutput contract read-run-output-result.v1 {\"type\":\"object\",\"additionalProperties\":true}\ncli display outcome as json\nscenario read-run-output root terminal\ngiven: a run id and the principal whose run it is\nwhen: the kernel reads the run evidence and selects its output\nthen: the outcome is the run output\noperation read-run-output.prepare kind invoke-port port read-run-output-prepare\noperation read-run-output.read kind invoke-port port read-run-output-read\noperation read-run-output.select kind invoke-port port read-run-output-select\nplatform bind read-run-output-prepare\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"read-run-output-prepare\"}\nplatform bind read-run-output-read\nplatform: generic-capability-invocation.v1\nconfig: {\"providerId\":\"generic-capability-invocation\",\"authoritySource\":\"DATABASE\",\"capabilityIdPath\":\"executionTarget\",\"namespacePath\":\"executionNamespace\",\"scenarioPath\":\"executionScenario\",\"requestPath\":\"dispatchRequest\",\"resultPath\":\"result\",\"lineageMode\":\"retain-nested-execution\"}\nplatform bind read-run-output-select\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"read-run-output-select\"}","isMcpTooling":false}';
EXEC model.apply_capability_from_dsl @document = N'{"contractId":"capability-from-dsl-change.v1","source":"capability read-run-graphs\nintent: The execution graphs of a run in the run store: read-run-evidence for the run and its principal, sliced to the graphs member, one per execution root.\noutcome: status, runId and the run graphs; a run the store does not hold answers the store NOT_FOUND\ninquiry: Which graphs did this run execute?\ninput contract read-run-graphs-request.v1 {\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"runId\"],\"properties\":{\"principalId\":{\"type\":\"string\"},\"runId\":{\"type\":\"string\"}}}\noutput contract read-run-graphs-result.v1 {\"type\":\"object\",\"additionalProperties\":true}\ncli display outcome as json\nscenario read-run-graphs root terminal\ngiven: a run id and the principal whose run it is\nwhen: the kernel reads the run evidence and selects its graphs\nthen: the outcome is the run graphs\noperation read-run-graphs.prepare kind invoke-port port read-run-graphs-prepare\noperation read-run-graphs.read kind invoke-port port read-run-graphs-read\noperation read-run-graphs.select kind invoke-port port read-run-graphs-select\nplatform bind read-run-graphs-prepare\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"read-run-graphs-prepare\"}\nplatform bind read-run-graphs-read\nplatform: generic-capability-invocation.v1\nconfig: {\"providerId\":\"generic-capability-invocation\",\"authoritySource\":\"DATABASE\",\"capabilityIdPath\":\"executionTarget\",\"namespacePath\":\"executionNamespace\",\"scenarioPath\":\"executionScenario\",\"requestPath\":\"dispatchRequest\",\"resultPath\":\"result\",\"lineageMode\":\"retain-nested-execution\"}\nplatform bind read-run-graphs-select\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"read-run-graphs-select\"}","isMcpTooling":false}';

COMMIT;
